// =====================================================
// EXTRACT MATCHING PROVIDER FROM WF3 RESPONSE
// =====================================================

const intakeProviderId = $('WF8 — Intake & Validator')
  .first()
  .json
  .provider_id;

const data = $input.first().json;

const services = data.services || [];

// Find matching provider inside services[]
const matchedService = services.find(s => {
  const provider = s.provider || {};

  return (
    provider.place_id === intakeProviderId ||
    provider.id === intakeProviderId ||
    provider.provider_id === intakeProviderId
  );
});

if (!matchedService) {
  return [{
    json: {
      error: 'No matching provider found',
      searched_for: intakeProviderId
    }
  }];
}

// Return only provider object
return [{
  json: matchedService.provider
}];

// ============================================================
// WF8 — OPTIMIZATION ENGINE (v3 — Provider Enrichment Fix)
// Fixes applied:
//   1. wf2Profile now reads from 'Code in JavaScript' (the extractor
//      that already filtered the matched provider from WF2's 3-5 results)
//      instead of reading raw WF2 response directly
//   2. Per-booking ui_actions added — frontend renders correct buttons
//      per booking with zero frontend logic changes
//   3. bookings[] array in response — full list with role + ui_actions
//   4. provider_action_locked bookings excluded from active workload
// ============================================================
const intake = $('WF8 — Intake & Validator').first().json;
const rawBookings = $('Fetch Provider Bookings').all().map(r => r.json);

// WF2 profile enrichment — reads from 'Code in JavaScript' extractor
// which already filtered the ONE matching provider from WF2's 3-5 results
let wf2Profile = null;
try {
  const enrichRaw = $('Code in JavaScript').first().json;
  // Code in JavaScript returns matchedService.provider directly
  // so enrichRaw IS the provider object — check it has valid data
  if (enrichRaw && !enrichRaw.error && (enrichRaw.place_id || enrichRaw.id || enrichRaw.rating !== undefined)) {
    wf2Profile = enrichRaw;
  } else {
    wf2Profile = null;
  }
} catch(e) {
  // WF2 enrichment unavailable — gracefully degrade
  wf2Profile = null;
}

const platformBookings = $('Fetch Platform Bookings').all().map(r => r.json);
const now = new Date();
const today = intake.today;
const maxDailyBookings = intake.max_daily_bookings;
const baseRate = intake.base_rate_pkr;
const myProviderId = intake.provider_id;

// ── CLASSIFY bookings by role ─────────────────────────────
// Row where provider_id = mine       → my original booking
// Row where reassigned_to_provider_id = mine → I am the NEW provider
// Row where status=rescheduled AND provider_id=mine → I was replaced

const myOriginalBookings = rawBookings.filter(b =>
  !b.reassigned_to_provider_id || b.reassigned_to_provider_id !== myProviderId
);
const reassignedToMe = rawBookings.filter(b =>
  b.reassigned_to_provider_id === myProviderId
);
const iLostBookings = myOriginalBookings.filter(b =>
  b.status === 'rescheduled' && b.provider_action_locked
);

// All bookings I should count for earnings
const allMyEarningBookings = [
  ...myOriginalBookings.filter(b => b.status === 'completed'),
  ...reassignedToMe.filter(b => b.status === 'completed')
];

// ── 1. WORKLOAD BALANCE ───────────────────────────────────
const confirmedToday = myOriginalBookings.filter(b =>
  b.booking_date === today &&
  (b.status === 'confirmed' || b.status === 'in_progress') &&
  !b.provider_action_locked
).concat(
  reassignedToMe.filter(b =>
    b.booking_date === today &&
    (b.status === 'confirmed' || b.status === 'in_progress')
  )
);

const completedAll = allMyEarningBookings;
const cancelledAll = myOriginalBookings.filter(b =>
  b.status === 'cancelled' || b.status === 'provider_cancelled' || b.status === 'no_show'
);
const utilizationRate = Math.round((confirmedToday.length / maxDailyBookings) * 100);
const workloadStatus =
  utilizationRate >= 100 ? 'FULL' :
  utilizationRate >= 75  ? 'BUSY' :
  utilizationRate >= 50  ? 'MODERATE' : 'AVAILABLE';

const bookedSlotsToday = confirmedToday.map(b => b.slot);
const allPossibleSlots = ['09:00','10:00','11:00','12:00','14:00','15:00','16:00','17:00'];
const openSlotsToday = allPossibleSlots.filter(s => !bookedSlotsToday.includes(s));

// ── 2. EARNINGS ───────────────────────────────────────────
const totalEarnings = completedAll.reduce((sum, b) => {
  return sum + (parseInt(b.final_price_pkr || b.price_pkr) || 0);
}, 0);
const avgEarningPerJob = completedAll.length > 0
  ? Math.round(totalEarnings / completedAll.length) : 0;

const platformCompleted = platformBookings.filter(b => b.status === 'completed');
const platformTotal = platformCompleted.reduce((sum, b) => {
  return sum + (parseInt(b.final_price_pkr || b.price_pkr) || 0);
}, 0);
const platformAvg = platformCompleted.length > 0
  ? Math.round(platformTotal / platformCompleted.length) : 1200;

const earningIndex = avgEarningPerJob > 0
  ? parseFloat((avgEarningPerJob / platformAvg).toFixed(2)) : 1.0;
const earningFairness =
  earningIndex >= 0.9 ? 'FAIR' :
  earningIndex >= 0.7 ? 'BELOW_AVERAGE' : 'LOW';

// ── 3. REPUTATION ─────────────────────────────────────────
const ratedBookings = completedAll.filter(b => b.customer_rating !== null && b.customer_rating !== undefined);
const ratings = ratedBookings.map(b => parseFloat(b.customer_rating));
const inAppAvgRating = ratings.length > 0
  ? parseFloat((ratings.reduce((a, b) => a + b, 0) / ratings.length).toFixed(2)) : null;

// Blend: in-app ratings take priority, fall back to WF2 Google Places
const googleRating = wf2Profile?.rating || null;
const googleReviewCount = wf2Profile?.review_count || 0;
const avgRating = inAppAvgRating !== null ? inAppAvgRating : googleRating;
const ratingSource = inAppAvgRating !== null ? 'in_app' : googleRating ? 'google_places' : null;

const flaggedCount = rawBookings.filter(b => b.flagged_for_review === true).length;
const fiveStarCount = ratings.filter(r => r === 5).length;
const lowRatingCount = ratings.filter(r => r <= 2).length;

const reputationHealth =
  flaggedCount > 3 ? 'AT_RISK' :
  flaggedCount > 1 ? 'MONITOR' :
  avgRating === null ? 'NEW' :
  avgRating >= 4.5 ? 'EXCELLENT' :
  avgRating >= 3.5 ? 'GOOD' : 'NEEDS_IMPROVEMENT';

// ── 4. CANCELLATION RATE ──────────────────────────────────
const totalBookings = myOriginalBookings.length;
const cancellationRate = totalBookings > 0
  ? parseFloat((cancelledAll.length / totalBookings).toFixed(2)) : 0;
const cancellationStatus =
  cancellationRate > 0.20 ? 'HIGH_RISK' :
  cancellationRate > 0.10 ? 'WARNING' : 'GOOD';

// ── 5. LOYALTY DETECTION ──────────────────────────────────
const emailCounts = {};
completedAll.forEach(b => {
  if (b.user_email) emailCounts[b.user_email] = (emailCounts[b.user_email] || 0) + 1;
});
const repeatCustomers = Object.entries(emailCounts)
  .filter(([, count]) => count >= 2)
  .map(([email, count]) => ({ email, bookings: count }));
const loyaltyInsight = repeatCustomers.length > 0
  ? `${repeatCustomers.length} repeat customer(s) detected. Loyalty discounts could boost retention.`
  : 'No repeat customers yet — focus on getting your first repeat booking.';

// ── 6. DEMAND FORECASTING ─────────────────────────────────
const slotDemand = {};
allPossibleSlots.forEach(s => { slotDemand[s] = 0; });
platformBookings.forEach(b => {
  if (b.slot && slotDemand[b.slot] !== undefined) slotDemand[b.slot]++;
});
const sortedByDemand = Object.entries(slotDemand).sort((a, b) => b[1] - a[1]);
const recommendedSlots = sortedByDemand.slice(0, 3).map(([slot, count]) => {
  const [h] = slot.split(':').map(Number);
  const period = h >= 12 ? 'PM' : 'AM';
  const hour = h > 12 ? h - 12 : h;
  return {
    slot,
    label: `${hour}:00 ${period}`,
    demand_score: count,
    is_open_today: openSlotsToday.includes(slot),
    recommendation: count >= 3 ? 'HIGH DEMAND — stay available'
      : count >= 1 ? 'MODERATE DEMAND — good to keep open'
      : 'LOW DEMAND'
  };
});

// ── 7. RATE OPTIMIZATION ──────────────────────────────────
let rateSuggestion;
if (earningFairness === 'LOW') {
  rateSuggestion = {
    current_base_rate: baseRate,
    suggested_base_rate: Math.round(platformAvg * 0.85),
    reason: 'Avg earning is significantly below platform average. Rate increase recommended.',
    loyalty_discount_suggestion: 'Offer 5% off to repeat customers while increasing base rate.'
  };
} else if (earningFairness === 'BELOW_AVERAGE') {
  rateSuggestion = {
    current_base_rate: baseRate,
    suggested_base_rate: Math.round(baseRate * 1.1),
    reason: 'Slightly below platform average. A 10% rate increase is recommended.',
    loyalty_discount_suggestion: 'Offer 5% off to repeat customers to balance the increase.'
  };
} else {
  rateSuggestion = {
    current_base_rate: baseRate,
    suggested_base_rate: baseRate,
    reason: 'Rate is fair relative to platform average. No change needed.',
    loyalty_discount_suggestion: repeatCustomers.length > 0
      ? `Consider a 5% loyalty discount for your ${repeatCustomers.length} repeat customer(s).`
      : null
  };
}

// ── 8. WF2 ENRICHED PROFILE ───────────────────────────────
// wf2Profile is the matched provider object from 'Code in JavaScript'
// which already filtered the correct provider from WF2's 3-5 results
const enrichedProfile = wf2Profile ? {
  provider_name: wf2Profile.name || intake.provider_name,
  google_rating: wf2Profile.rating,
  review_count: wf2Profile.review_count,
  address: wf2Profile.address,
  coordinates: wf2Profile.coordinates,
  distance_km: wf2Profile.distance_km,
  verified: wf2Profile.verified,
  reputation_score: wf2Profile.reputation_score,
  on_time_score: wf2Profile.on_time_score,
  at_capacity: wf2Profile.at_capacity,
  google_maps_url: wf2Profile.google_maps_url,
  photos: wf2Profile.photos || [],
  complexity_levels: wf2Profile.complexity_levels || [],
  services: wf2Profile.services || [],
  base_rate_pkr: wf2Profile.base_rate_pkr,
  availability_slots: wf2Profile.availability_slots || [],
  computed_score: wf2Profile.computed_score,
  cancellation_rate: wf2Profile.cancellation_rate,
  source: 'wf2_google_places_live'
} : {
  provider_name: intake.provider_name,
  note: 'WF2 enrichment unavailable — send service_type + location in request for full profile',
  source: 'unavailable'
};

// ── 9. RESCHEDULE IMPACT SUMMARY ──────────────────────────
const rescheduleImpact = {
  bookings_lost_to_reschedule: iLostBookings.length,
  bookings_gained_from_reschedule: reassignedToMe.length,
  net_reschedule_impact: reassignedToMe.length - iLostBookings.length,
  note: iLostBookings.length > 0
    ? `${iLostBookings.length} booking(s) were rescheduled away from you. These no longer appear in your active workload.`
    : 'No bookings rescheduled away from you.'
};

// ── 10. OPTIMIZATION TIPS ─────────────────────────────────
const tips = [
  utilizationRate === 0
    ? '🔔 No bookings today — you are visible for urgent same-day requests.'
    : utilizationRate < 50
    ? `📅 Only ${confirmedToday.length}/${maxDailyBookings} slots filled today.`
    : null,
  earningFairness !== 'FAIR'
    ? `💰 Your avg earning (PKR ${avgEarningPerJob}) is below platform avg (PKR ${platformAvg}).`
    : null,
  recommendedSlots[0]?.is_open_today
    ? `⏰ Peak slot ${recommendedSlots[0].slot} is still open today!`
    : null,
  completedAll.length < 5
    ? '⭐ Complete more jobs to build your rating history.'
    : null,
  lowRatingCount > 0
    ? `⚠️ ${lowRatingCount} low rating(s) detected. Review your service checklist.`
    : null,
  flaggedCount > 0
    ? `🚩 ${flaggedCount} booking(s) flagged for review. Address disputes to protect ranking.`
    : null,
  cancellationStatus !== 'GOOD'
    ? `❌ Cancellation rate ${(cancellationRate * 100).toFixed(0)}% is ${cancellationStatus}.`
    : null,
  repeatCustomers.length > 0 ? `🔁 ${loyaltyInsight}` : null,
  iLostBookings.length > 0
    ? `🔄 ${iLostBookings.length} booking(s) were reassigned away — maintain availability to avoid this.`
    : null,
  `📊 Utilization today: ${utilizationRate}% (${confirmedToday.length}/${maxDailyBookings} slots)`
].filter(Boolean);

// ── 11. PER-BOOKING UI ACTIONS ────────────────────────────
// Frontend reads booking.ui_actions to render the correct buttons.
// Same pattern as WF5 show_track_button / show_feedback_button.
function getBookingUiActions(b, role) {
  const status = b.status;
  const trackingLocked = !!b.tracking_locked;

  if (role === 'lost_to_reschedule') {
    return {
      show_track_button: false,
      show_cancel_button: false,
      show_report_button: false,
      show_feedback_button: true,
      primary_label: 'Booking Reassigned',
      secondary_label: 'Leave Feedback',
      reason: 'booking_rescheduled_to_new_provider'
    };
  }

  if ((status === 'provider_cancelled' || status === 'rescheduled') && b.provider_action_locked) {
    return {
      show_track_button: false,
      show_cancel_button: false,
      show_report_button: false,
      show_feedback_button: true,
      primary_label: status === 'rescheduled' ? 'Booking Reassigned' : 'Cancelled',
      secondary_label: 'Leave Feedback',
      reason: status === 'rescheduled' ? 'booking_rescheduled_to_new_provider' : 'booking_cancelled_by_provider'
    };
  }

  if (status === 'completed') {
    return {
      show_track_button: false,
      show_cancel_button: false,
      show_report_button: true,
      show_feedback_button: true,
      primary_label: 'Completed',
      secondary_label: 'Leave Feedback',
      reason: 'booking_completed'
    };
  }

  if (status === 'confirmed' || status === 'in_progress') {
    return {
      show_track_button: !trackingLocked,
      show_cancel_button: true,
      show_report_button: false,
      show_feedback_button: false,
      primary_label: status === 'in_progress' ? 'In Progress' : 'Track',
      secondary_label: 'Cancel',
      reason: 'booking_active'
    };
  }

  return {
    show_track_button: false,
    show_cancel_button: false,
    show_report_button: false,
    show_feedback_button: false,
    primary_label: status || 'Unknown',
    secondary_label: null,
    reason: 'unknown_status'
  };
}

const bookingsList = [
  // My original bookings (excluding lost ones — they go in their own bucket)
  ...myOriginalBookings
    .filter(b => !iLostBookings.includes(b))
    .map(b => ({
      booking_id: b.booking_id,
      service_type: b.service_type,
      booking_date: b.booking_date,
      slot: b.slot,
      user_name: b.user_name || b.user_email,
      location: b.location,
      status: b.status,
      price_pkr: b.final_price_pkr || b.price_pkr,
      provider_action_locked: !!b.provider_action_locked,
      tracking_locked: !!b.tracking_locked,
      role: 'original',
      ui_actions: getBookingUiActions(b, 'original')
    })),

  // Bookings reassigned TO this provider by WF7
  ...reassignedToMe.map(b => ({
    booking_id: b.booking_id,
    service_type: b.service_type,
    booking_date: b.booking_date,
    slot: b.slot,
    user_name: b.user_name || b.user_email,
    location: b.location,
    status: b.status,
    price_pkr: b.final_price_pkr || b.price_pkr,
    provider_action_locked: !!b.provider_action_locked,
    tracking_locked: !!b.tracking_locked,
    role: 'reassigned_to_me',
    ui_actions: getBookingUiActions(b, 'reassigned_to_me')
  })),

  // Bookings this provider LOST to reschedule
  ...iLostBookings.map(b => ({
    booking_id: b.booking_id,
    service_type: b.service_type,
    booking_date: b.booking_date,
    slot: b.slot,
    user_name: b.user_name || b.user_email,
    location: b.location,
    status: b.status,
    price_pkr: b.final_price_pkr || b.price_pkr,
    provider_action_locked: true,
    tracking_locked: true,
    role: 'lost_to_reschedule',
    ui_actions: getBookingUiActions(b, 'lost_to_reschedule')
  }))
];

// ── ANTIGRAVITY TRACE ─────────────────────────────────────
const antigravityTrace = {
  workflow: 'WF8-ProviderOptimization-v3',
  reasoning: [
    `STEP 1 — Fetched ${rawBookings.length} bookings via OR query (provider_id OR reassigned_to_provider_id).`,
    `STEP 2 — Classified: ${myOriginalBookings.length} original, ${reassignedToMe.length} reassigned-to-me, ${iLostBookings.length} lost-to-reschedule.`,
    `STEP 3 — Workload today: ${confirmedToday.length}/${maxDailyBookings} (${utilizationRate}%). Status: ${workloadStatus}.`,
    `STEP 4 — Earnings from ${completedAll.length} completed jobs (incl. reassigned): PKR ${totalEarnings}. Avg: PKR ${avgEarningPerJob}. Fairness: ${earningFairness}.`,
    `STEP 5 — Reputation: ${ratings.length} in-app ratings, avg ${inAppAvgRating ?? 'N/A'}. Google Places: ${googleRating ?? 'N/A'} (${googleReviewCount} reviews). Health: ${reputationHealth}.`,
    `STEP 6 — Cancellations: ${cancelledAll.length}/${totalBookings}. Rate: ${(cancellationRate*100).toFixed(0)}%. Status: ${cancellationStatus}.`,
    `STEP 7 — WF2 enrichment: ${wf2Profile ? 'SUCCESS — matched provider profile merged from Code in JavaScript extractor' : 'UNAVAILABLE — graceful degradation'}.`,
    `STEP 8 — Reschedule impact: lost ${iLostBookings.length}, gained ${reassignedToMe.length}.`,
    `STEP 9 — Generated ${tips.length} tips. Built ${bookingsList.length} booking entries with ui_actions.`
  ],
  data_sources: {
    provider_bookings: 'Supabase OR query: provider_id OR reassigned_to_provider_id',
    platform_bookings: 'Supabase all completed rows',
    ratings: 'customer_rating from WF5 + Google Places from WF2',
    flags: 'flagged_for_review from WF6',
    cancellations: 'cancellation_reason from WF7',
    earnings: 'final_price_pkr from WF5 completed stage',
    enrichment: wf2Profile ? 'WF2 — matched provider via Code in JavaScript extractor' : 'unavailable'
  },
  confidence: 95
};

console.log('=== WF8 Optimization Engine v3 ===');
console.log('Original bookings:', myOriginalBookings.length, '| Reassigned to me:', reassignedToMe.length);
console.log('Utilization:', utilizationRate + '%', workloadStatus);
console.log('WF2 enrich:', wf2Profile ? `OK — ${wf2Profile.name || intake.provider_id}` : 'SKIP');

return [{ json: {
  status: 'provider_dashboard',
  provider_id: intake.provider_id,
  provider_name: enrichedProfile.provider_name || intake.provider_name,
  date: today,

  profile: enrichedProfile,

  workload: {
    bookings_today: confirmedToday.length,
    max_capacity: maxDailyBookings,
    utilization_rate_pct: utilizationRate,
    status: workloadStatus,
    slots_booked_today: bookedSlotsToday,
    slots_open_today: openSlotsToday,
    slots_remaining: openSlotsToday.length
  },

  earnings: {
    total_completed_jobs: completedAll.length,
    total_earnings_pkr: totalEarnings,
    avg_per_job_pkr: avgEarningPerJob,
    platform_avg_pkr: platformAvg,
    earning_index: earningIndex,
    earning_fairness: earningFairness,
    note: 'Includes earnings from bookings reassigned to this provider via WF7'
  },

  reputation: {
    avg_rating: avgRating,
    rating_source: ratingSource,
    google_rating: googleRating,
    google_review_count: googleReviewCount,
    in_app_avg_rating: inAppAvgRating,
    total_in_app_ratings: ratings.length,
    five_star_count: fiveStarCount,
    low_rating_count: lowRatingCount,
    flagged_bookings: flaggedCount,
    reputation_health: reputationHealth
  },

  cancellations: {
    total_cancelled: cancelledAll.length,
    cancellation_rate_pct: Math.round(cancellationRate * 100),
    status: cancellationStatus
  },

  reschedule_impact: rescheduleImpact,

  loyalty: {
    repeat_customers: repeatCustomers.length,
    repeat_customer_list: repeatCustomers.slice(0, 5),
    insight: loyaltyInsight,
    suggested_discount_pct: repeatCustomers.length > 0 ? 5 : 0
  },

  demand_forecast: {
    recommended_slots: recommendedSlots,
    peak_insight: `Peak demand is at ${recommendedSlots[0]?.slot || '10:00'}. Being available then maximizes bookings.`
  },

  bookings: bookingsList,

  rate_optimization: rateSuggestion,
  optimization_tips: tips,
  antigravity_trace: antigravityTrace,

  simulated_whatsapp:
    `Provider Dashboard — Khadmat AI v3\n` +
    `Date: ${today}\n` +
    `Workload: ${confirmedToday.length}/${maxDailyBookings} (${workloadStatus})\n` +
    `Earnings avg: PKR ${avgEarningPerJob} (${earningFairness})\n` +
    `Rating: ${avgRating ?? 'No ratings yet'}/5 (${reputationHealth})\n` +
    `Reschedule: -${iLostBookings.length} lost / +${reassignedToMe.length} gained\n` +
    `Top tip: ${tips[0] || 'Keep it up!'}`,

  workflow: 'WF8-ProviderOptimization-v3',
  timestamp: now.toISOString()
}}];

// ============================================================
// WF8 — INTAKE & VALIDATOR
// Expected fields:
//   provider_id     (required — Google Place ID or email)
//   provider_name   (optional)
//   base_rate_pkr   (optional, default 900)
//   max_daily_bookings (optional, default 4)
// ============================================================
const body = $input.first().json.body || $input.first().json;

if (!body.provider_id) {
  return [{ json: {
    status: 'validation_error',
    message: 'provider_id is required',
    workflow: 'WF8-Intake'
  }}];
}

const today = new Date().toISOString().split('T')[0];

console.log('=== WF8 Provider Optimization ===');
console.log('Provider ID:', body.provider_id);
console.log('Date:', today);

return [{ json: {
  provider_id: body.provider_id,
  provider_name: body.provider_name || 'Provider',
  base_rate_pkr: body.base_rate_pkr || 900,
  max_daily_bookings: body.max_daily_bookings || 4,
  today
}}];

// ============================================================
// MERGE: Booking + Provider Enriched Profile
// Input: array with mixed booking + provider profile objects
// Output: clean merged dashboard-ready structure
// ============================================================

const items = $input.all().map(i => i.json);

// Separate booking and provider profile
const booking = items.find(i => i.status); // has status → booking
const provider = items.find(i => i.place_id || i.rating !== undefined);

// Safety check
if (!booking || !provider) {
  return [{
    json: {
      error: "Missing booking or provider profile in input",
      received: items
    }
  }];
}

// ============================================================
// MERGED OUTPUT
// ============================================================

const merged = {
  // --- Booking info ---
  booking: {
    slot: booking.slot,
    status: booking.status,
    price_pkr: booking.price_pkr,
    final_price_pkr: booking.final_price_pkr
  },

  // --- Provider info ---
  provider: {
    id: provider.id,
    name: provider.name,
    owner: provider.owner,
    services: provider.services,
    areas: provider.areas,
    coordinates: provider.coordinates,
    base_rate_pkr: provider.base_rate_pkr,
    rating: provider.rating,
    review_count: provider.review_count,
    on_time_score: provider.on_time_score,
    cancellation_rate: provider.cancellation_rate,
    availability_slots: provider.availability_slots,
    active_bookings: provider.active_bookings,
    max_daily_bookings: provider.max_daily_bookings,
    at_capacity: provider.at_capacity,
    distance_km: provider.distance_km,
    verified: provider.verified,
    reputation_score: provider.reputation_score,
    google_maps_url: provider.google_maps_url,
    photos: provider.photos,
    computed_score: provider.computed_score,
    score_breakdown: provider.score_breakdown
  },

  // --- Derived insights (optional but useful) ---
  insights: {
    is_available: provider.availability_slots?.includes(booking.slot),
    price_match: booking.final_price_pkr <= provider.base_rate_pkr,
    distance_score: provider.score_breakdown?.distance || null,
    recommendation_score: provider.computed_score || null
  }
};

return [{ json: merged }];
